<?php $this->assign('title', 'Pago #' . (int)$payment->id); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><a class="small" href="/admin/payments">← Pagos</a><h1 class="h2 mb-1">Pago #<?= (int)$payment->id ?></h1><p class="text-muted mb-0"><?= h($payment->internal_reference) ?> · <?= h($payment->user->email ?? '') ?></p></div><span class="badge text-bg-secondary align-self-center"><?= h($payment->status) ?></span></div>
<div class="row g-4"><div class="col-lg-8"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Resultado de la transacción</h2><dl class="row mb-0"><dt class="col-sm-4">Plan</dt><dd class="col-sm-8"><?= h($payment->plan_slug) ?></dd><dt class="col-sm-4">Monto esperado</dt><dd class="col-sm-8">$<?= number_format((int)$payment->expected_amount, 0, ',', '.') ?> <?= h($payment->currency) ?></dd><dt class="col-sm-4">Monto confirmado</dt><dd class="col-sm-8"><?= $payment->confirmed_amount !== null ? '$' . number_format((int)$payment->confirmed_amount, 0, ',', '.') : '—' ?></dd><dt class="col-sm-4">Orden / sesión</dt><dd class="col-sm-8"><code><?= h($payment->buy_order) ?></code> / <code><?= h($payment->session_id) ?></code></dd><dt class="col-sm-4">Autorización</dt><dd class="col-sm-8"><?= h($payment->authorization_code ?: '—') ?></dd><dt class="col-sm-4">Error</dt><dd class="col-sm-8"><?= h($payment->error_code ?: '—') ?></dd><dt class="col-sm-4">Suscripción</dt><dd class="col-sm-8"><?php if ($payment->subscription): ?><a href="/admin/subscriptions/<?= (int)$payment->subscription->id ?>">#<?= (int)$payment->subscription->id ?></a><?php else: ?>—<?php endif; ?></dd></dl></div></section><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Payloads sanitizados</h2><h3 class="h6">Solicitud</h3><pre class="payload bg-light p-2 rounded"><?= h(json_encode($requestPayload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre><h3 class="h6">Respuesta</h3><pre class="payload bg-light p-2 rounded"><?= h(json_encode($responsePayload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre></div></section><section class="card admin-card"><div class="card-body"><h2 class="h5">Auditoría</h2><?php foreach ($audits as $audit): ?><div class="border-bottom py-2"><strong class="small"><?= h($audit->action) ?></strong><small class="d-block text-muted"><?= h($audit->created) ?></small></div><?php endforeach; ?></div></section></div>
<aside class="col-lg-4"><section class="card admin-card"><div class="card-body"><h2 class="h5">Acciones</h2><?php if ($payment->provider === 'webpay_plus' && in_array($payment->status, ['pending', 'authorized'], true)): ?><?= $this->Form->create(null, ['url' => '/admin/payments/' . $payment->id . '/reconcile', 'class' => 'mb-2', 'data-admin-confirm' => '¿Consultar y conciliar este pago con Webpay?']) ?><textarea class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo de conciliación"></textarea><button class="btn btn-primary w-100">Consultar y conciliar Webpay</button><?= $this->Form->end() ?><?php endif; ?><?php if (in_array($payment->status, ['pending', 'authorized'], true)): ?><?= $this->Form->create(null, ['url' => '/admin/payments/' . $payment->id . '/cancel', 'class' => 'mb-2', 'data-admin-confirm' => '¿Cancelar esta orden interna?']) ?><textarea class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo de cancelación"></textarea><button class="btn btn-outline-danger w-100">Cancelar orden interna</button><?= $this->Form->end() ?><?php endif; ?><?= $this->Form->create(null, ['url' => '/admin/payments/' . $payment->id . '/review', 'data-admin-confirm' => '¿Marcar este pago para revisión?']) ?><textarea class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo de revisión"></textarea><button class="btn btn-outline-secondary w-100">Marcar para revisión</button><?= $this->Form->end() ?></div></section></aside></div>
